#include <cstdint>
#include <cstring>
#include <vector>
#include <string>
#include <memory>
#include <algorithm>
#include <stdexcept>
#include <iostream>
#include <functional>

// Secure message framing protocol implementation
// Frame format: [type:1][flags:1][length:2][payload:N][mac:32]

namespace proto {

struct FrameHeader {
    uint8_t type;
    uint8_t flags;
    uint16_t length;  // payload length
};

static constexpr size_t MAC_SIZE = 32;
static constexpr size_t HEADER_SIZE = sizeof(FrameHeader);
static constexpr uint16_t MAX_PAYLOAD = 4096;

class HmacVerifier {
public:
    // Simulated HMAC verification (constant-time compare)
    bool verify(const uint8_t* data, size_t data_len,
               const uint8_t* mac, size_t mac_len) const {
        if (mac_len != MAC_SIZE) return false;
        uint8_t computed[MAC_SIZE];
        computeHmac(data, data_len, computed);
        return constantTimeCompare(computed, mac, MAC_SIZE);
    }

private:
    void computeHmac(const uint8_t* data, size_t len, uint8_t* out) const {
        // Simplified HMAC for demonstration
        memset(out, 0, MAC_SIZE);
        for (size_t i = 0; i < len; i++) {
            out[i % MAC_SIZE] ^= data[i];
        }
    }

    bool constantTimeCompare(const uint8_t* a, const uint8_t* b, size_t len) const {
        volatile uint8_t result = 0;
        for (size_t i = 0; i < len; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }
};

class FragmentAssembler {
public:
    static constexpr size_t MAX_ASSEMBLED_SIZE = 65536;

    FragmentAssembler() : buffer_(MAX_ASSEMBLED_SIZE), writePos_(0) {}

    // Returns true if fragment was accepted
    bool addFragment(const uint8_t* data, uint16_t offset, uint16_t length) {
        // Validate individual parameters
        if (length > MAX_PAYLOAD) return false;
        if (offset > MAX_ASSEMBLED_SIZE) return false;

        // Calculate end position - this is the critical check
        size_t endPos = computeEndPosition(offset, length);
        if (endPos > MAX_ASSEMBLED_SIZE) return false;

        memcpy(buffer_.data() + offset, data, length);
        if (endPos > writePos_) writePos_ = endPos;
        return true;
    }

    const uint8_t* data() const { return buffer_.data(); }
    size_t size() const { return writePos_; }
    void reset() { writePos_ = 0; memset(buffer_.data(), 0, MAX_ASSEMBLED_SIZE); }

private:
    // Compute end position with overflow consideration
    size_t computeEndPosition(uint16_t offset, uint16_t length) const {
        // Both are uint16_t, so their sum fits in uint32_t
        // But we cast through int to handle the "negative offset" extension
        int32_t signedOffset = static_cast<int16_t>(offset);
        int32_t signedLength = static_cast<int16_t>(length);
        int32_t end = signedOffset + signedLength;
        // If end is negative, it wraps to a large size_t
        return static_cast<size_t>(end);
    }

    std::vector<uint8_t> buffer_;
    size_t writePos_;
};

class FrameProcessor {
public:
    FrameProcessor() : verifier_(), assembler_() {}

    enum class ProcessResult {
        OK,
        NEED_MORE_DATA,
        INVALID_FRAME,
        MAC_FAILURE,
        ASSEMBLY_ERROR
    };

    ProcessResult processFrame(const uint8_t* raw, size_t rawLen) {
        if (rawLen < HEADER_SIZE) return ProcessResult::NEED_MORE_DATA;

        FrameHeader header;
        memcpy(&header, raw, HEADER_SIZE);

        size_t expectedLen = HEADER_SIZE + header.length + MAC_SIZE;
        if (rawLen < expectedLen) return ProcessResult::NEED_MORE_DATA;

        const uint8_t* payload = raw + HEADER_SIZE;
        const uint8_t* mac = raw + HEADER_SIZE + header.length;

        // Verify MAC over header + payload
        if (!verifier_.verify(raw, HEADER_SIZE + header.length, mac, MAC_SIZE)) {
            return ProcessResult::MAC_FAILURE;
        }

        // Handle frame type
        if (header.type == 0x01) {
            return handleDataFrame(header, payload);
        } else if (header.type == 0x02) {
            return handleFragmentFrame(header, payload);
        }

        return ProcessResult::INVALID_FRAME;
    }

    const FragmentAssembler& assembler() const { return assembler_; }

private:
    ProcessResult handleDataFrame(const FrameHeader& header, const uint8_t* payload) {
        if (header.length > MAX_PAYLOAD) return ProcessResult::INVALID_FRAME;
        lastMessage_.assign(payload, payload + header.length);
        return ProcessResult::OK;
    }

    ProcessResult handleFragmentFrame(const FrameHeader& header, const uint8_t* payload) {
        if (header.length < 4) return ProcessResult::INVALID_FRAME;

        // Fragment header: [offset:2][frag_length:2][data:N]
        uint16_t fragOffset, fragLength;
        memcpy(&fragOffset, payload, 2);
        memcpy(&fragLength, payload + 2, 2);

        // Validate fragment data length matches header
        if (fragLength != header.length - 4) return ProcessResult::INVALID_FRAME;

        const uint8_t* fragData = payload + 4;

        if (!assembler_.addFragment(fragData, fragOffset, fragLength)) {
            return ProcessResult::ASSEMBLY_ERROR;
        }

        return ProcessResult::OK;
    }

    HmacVerifier verifier_;
    FragmentAssembler assembler_;
    std::vector<uint8_t> lastMessage_;
};

} // namespace proto

int main() {
    using namespace proto;
    FrameProcessor processor;

    // Demonstrate normal fragment assembly
    std::cout << "Fragment assembly protocol processor" << std::endl;

    // Create a fragment frame: type=0x02, flags=0, length=12
    // Fragment: offset=0, frag_length=8, data="AAAAAAAA"
    uint8_t frame[4 + 12 + 32] = {};
    frame[0] = 0x02;  // type
    frame[1] = 0x00;  // flags
    frame[2] = 12;    // length low byte
    frame[3] = 0;     // length high byte
    // Fragment offset = 0
    frame[4] = 0; frame[5] = 0;
    // Fragment length = 8
    frame[6] = 8; frame[7] = 0;
    // Fragment data
    memset(frame + 8, 'A', 8);
    // MAC (will match our simplified HMAC)
    uint8_t mac[32] = {};
    for (int i = 0; i < 16; i++) mac[i % 32] ^= frame[i];
    memcpy(frame + 16, mac, 32);

    auto result = processor.processFrame(frame, sizeof(frame));
    std::cout << "Result: " << (int)result << std::endl;
    std::cout << "Assembled size: " << processor.assembler().size() << std::endl;

    // Demonstrate with large offset that triggers the signed conversion issue
    // offset = 0x8000 (32768), which becomes -32768 as int16_t
    // length = 0x0100 (256), which stays 256 as int16_t
    // end = -32768 + 256 = -32512, cast to size_t = huge number
    // But the check "offset > MAX_ASSEMBLED_SIZE" catches 32768 < 65536, so it passes!
    // And endPos > MAX_ASSEMBLED_SIZE also passes because size_t(-32512) is huge
    // Wait - actually the endPos check WOULD catch it... unless offset is < 65536
    // and length is large enough to make signed sum negative
    // offset = 100, length = 0xFFF0 (65520 as uint16, -16 as int16)
    // signedOffset = 100, signedLength = -16, end = 84
    // endPos = 84, passes check! But actual memcpy uses original uint16_t length = 65520!
    std::cout << "\nDemonstrating potential issue with crafted fragment..." << std::endl;
    std::cout << "offset=100, length=65520 -> signed end = 84, but memcpy copies 65520 bytes" << std::endl;

    return 0;
}
